"""PE organizer candidate real importer/finalizer/schema/negative checks, no extraction."""
import collections,copy,datetime,hashlib,json,pathlib,subprocess,sys
import pymupdf,jsonschema
R=pathlib.Path(__file__).resolve().parents[3];O=pathlib.Path(__file__).parent;sys.path.insert(0,str(R/'pipeline'));import ingest
SID='pe-curriculo-ei';s=next(s for s in json.loads((R/'data/manifests/northeast.json').read_text()) if s['id']==SID);clone=copy.deepcopy(s);clone['uncoded_items_path']='data/manifests/uncoded/pe-ei-objectives-items.json';clone['adapter_authority']={'coded_learning_pages':[87,117],'uncoded_page_sections_pages':[84,86]}
side=R/clone['uncoded_items_path'];before=hashlib.sha256(side.read_bytes()).hexdigest();census=json.loads((O/'pe-ei-organizer-cell-census.json').read_text());expected=set(census['expected_item_ids']);assert len(expected)==135 and census['expected_objectives']==115
cache=R/'data/extracted'/f'{s["sha256"]}-{ingest.EXTRACTION_REVISION}.json';ex=ingest.read_extraction_cache(cache);assert ex['sha256']==s['sha256'] and not ex['ocr_pending'];adapt=ingest.source_uncoded_items([clone],{SID:ex});final=ingest.finalize_items(ex['items']+adapt,[clone]);byid={r['id']:r for r in final};integrated=[r for r in final if r.get('document_specific_adapter')];assert {r['id'] for r in integrated}==expected
schema=json.loads((R/'data/schema/1.1.0.json').read_text());learning={'$ref':'#/$defs/Learning','$defs':schema['$defs']};fragments=0
with pymupdf.open(R/s['local_path']) as pdf:
 for r in integrated:
  jsonschema.validate(r,learning);assert ingest.evidence_check(r,ex,pdf),r['id'];fragments+=len(r['evidence']);cursor=r;seen=set()
  while cursor.get('parent_id'):
   assert cursor['parent_id'] in byid and cursor['id'] not in seen;seen.add(cursor['id']);cursor=byid[cursor['parent_id']]
 objectives=[r for r in integrated if r['kind']=='objetivo_aprendizagem'];assert len(objectives)==115
 assert {r['code'] for r in objectives}=={c['code'] for c in census['source_cells']}
 assert all(r['positions'][0]['stage']=='EI' and r['positions'][0]['age_group'] and r['positions'][0]['component'] and r['positions'][0]['years'] is None and r['positions'][0]['period'] is None for r in objectives)
 assert not [r for r in final if r.get('code') and not r.get('document_specific_adapter') and any(87<=e['page']<=117 for e in r['evidence'])]
 assert not [r for r in final if not r.get('document_specific_adapter') and r['evidence'][0]['method']=='pymupdf-page-section' and 84<=r['evidence'][0]['page']<=86]
 for code,pn,pair in [('EI02S06PE',101,'TS'),('EI003EF11PE',117,'EF')]:
  r=next(r for r in objectives if r['code']==code);assert r['evidence'][0]['page']==pn and r['source_context']['code_conforms_to_source_pair_legend'] is False;assert r['parent_id'].endswith('-field-'+pair.lower());assert r['source_context']['nonconforming_identifier_evidence'];assert ' ' in r['code_original'] or code=='EI003EF11PE'
  altered=copy.deepcopy(r);altered['code']='EI02TS06PE' if code=='EI02S06PE' else 'EI03EF11PE';altered['evidence']=[e for e in altered['evidence'] if e.get('evidence_role')!='code_locator'];assert not ingest.evidence_check(altered,ex,pdf),'Invented code correction must fail actual source evidence'
for c in ['EI02TS03PE','EI02EO05PE']:
 r=next(r for r in objectives if r['code']==c);assert r['text'] not in ('','PE)') and len(r['text'])>80
assert len([r for r in integrated if r['kind']=='grupo_etario'])==3 and len([r for r in integrated if r['kind']=='campo_experiencia'])==15
subprocess.run([sys.executable,str(O/'build-pe-ei-objectives-adapter.py')],cwd=R,check=True,stdout=subprocess.DEVNULL);after=hashlib.sha256(side.read_bytes()).hexdigest();assert before==after
report={'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'actor_type':'automated','actor_id':'codex:data_northeast:PE_candidate_real_importer','source_id':SID,'artifact_sha256':s['sha256'],'sidecar_path':clone['uncoded_items_path'],'sidecar_sha256':before,'extraction_revision':ex['extraction_revision'],'cache_sha256':hashlib.sha256(cache.read_bytes()).hexdigest(),'current_original_Source_cache_config_matches':ex['extraction_config_sha256']==ingest.extraction_config_hash(s),'source_defined_age_groups':3,'source_defined_fields_per_group':5,'source_defined_coded_objectives':115,'independent_adapter_IDs':135,'actual_adapter_records':len(integrated),'literal_fragments_checked':fragments,'source_generic_inputs':len(ex['items']),'final_records_including_remaining_generic_context':len(final),'parents_resolved':sum(bool(r['parent_id']) for r in integrated),'schema_failures':0,'orphans':0,'cycles':0,'generic_coded_records_surviving_repaired_scope':0,'literal_nonconforming_codes_preserved':['EI02S06PE','EI003EF11PE'],'two_invented_code_corrections_rejected':True,'code_original_group_whitespace_preserved':True,'idempotent_sidecar_bytes':before==after,'by_kind':dict(collections.Counter(r['kind'] for r in integrated)),'proposed_authority':clone['adapter_authority'],'provenance_status':s.get('provenance_status'),'actual_Source_binding_changed':False,'extraction_invoked':False,'peer_status':'pending','result':'passed','whole_source_reconciled':False,'UF_ready':False,'scope':'Complete coded organizer and its headers/legend, real importer/finalizer using immutable existing1.5 source cache and cloned Source. Source134p rights/narrative/credits/references are not reconciled. Primary distribution chain pending; no official-chain/current-adoption or pedagogical human review claim.'}
(O/'pe-ei-organizer-real-import-verification.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n');print(json.dumps(report,ensure_ascii=False))
